  body {
    line-height: 1;
    min-height: 100dvh;
  }
  #root {
    min-height: 100%;
  }
  h1, h2, h3, h4, h5, h6 {
    font-size: inherit;
    font-weight: inherit;
  }
  img {
    display: block;
  }
  strong {
    font-weight: 600;
  }
  menu, ol, ul {
    list-style: none;
  }
  blockquote, q {
    quotes: none;
  }
  blockquote::before, blockquote::after, q::before, q::after {
    content: none;
  }
  table {
    border-collapse: collapse;
    border-spacing: 0;
  }
  a, button {
    cursor: pointer;
  }
  button {
    padding: 0;
    font-family: inherit;
  }
  hidden {
    display: none;
  }
  :disabled {
    cursor: not-allowed;
  }
  sup {
    vertical-align: super;
    font-size: smaller;
  }
  sub {
    vertical-align: sub;
    font-size: smaller;
